    gc: &mut GlobalContext,
    paint_: &Paint,
    fill_rule_: FillRule,
    on_text: bool,
    surface: &mut Surface,
    state: &State,
    shape: Option<&Shape>,
) -> SourceResult<Fill> {
    let (paint, opacity) =
        convert_paint(gc, paint_, on_text, surface, state, shape, false)?;

